const DEG=Math.PI/180;
function run(opts){
  const b={accel:262,maxSpeed:435,lift:1.0,balance:1.0};
  const crash=opts.crash??103, heatMax=opts.heatMax??0.24, heatDiv=opts.heatDiv??22, leanF=-39;
  let speed=92,theta=0,omega=0,gas=0,wt=0,t=0;
  const dt=1/120;
  let log=[];
  for(let i=0;i<120*30;i++){
    t+=dt;
    gas=Math.min(1,gas+dt*7.5);
    const drag=0.17*speed+9;
    speed += gas*b.accel-drag;
    if(speed>b.maxSpeed) speed=b.maxSpeed;
    const sf=Math.min(speed/155,1);
    const lf=0.3+0.7*sf;
    const heat=1+Math.min(wt/heatDiv,heatMax);
    const lift=gas*120*b.lift*lf*heat;
    const grav=118*Math.sin(theta*DEG)*(1+0.06*Math.min(theta,110)/90);
    const leanT=opts.lean?leanF:0;
    const damp=3.15*b.balance*omega;
    const chatter=Math.sin(t*10.7)*0.55*sf;
    const wander=Math.sin(t*1.35+wt*0.7)*(2.2+Math.min(wt,14)*0.75)*sf;
    omega+=(lift+leanT-grav-damp+chatter+wander)*dt;
    theta+=omega*dt;
    if(theta<0){theta=0;omega*=-0.18;}
    if(theta>13) wt+=dt; else wt=0;
    if(theta>crash) return {t:+t.toFixed(1),theta:+theta.toFixed(1),omega:+omega.toFixed(1),wt:+wt.toFixed(1),crash:true,log};
    if(i%120===0)log.push({t:Math.round(t),th:+theta.toFixed(1),sp:+speed.toFixed(0),wt:+wt.toFixed(1)});
  }
  return {t:+t.toFixed(1),theta:+theta.toFixed(1),wt:+wt.toFixed(1),crash:false,log};
}
console.log('hold gas heat .24',run({}));
console.log('hold gas heat .12',run({heatMax:.12,heatDiv:18}));
console.log('hold gas heat 0',run({heatMax:0}));
// recovery from high angle with lean fwd and gas released
function recover(heatMax,crash,leanF){
  let speed=435,theta=100,omega=30,gas=1,wt=9,t=0;const dt=1/120;
  for(let i=0;i<120*5;i++){
    t+=dt; gas=Math.max(0,gas-dt*12);
    speed=Math.max(0,speed-(0.17*speed+9)*dt);
    const sf=Math.min(speed/155,1), lf=.3+.7*sf;
    const heat=1+Math.min(wt/18,heatMax);
    const lift=gas*120*lf*heat;
    const grav=118*Math.sin(theta*DEG)*(1+0.06*Math.min(theta,110)/90);
    const damp=3.15*omega;
    omega+=(lift+leanF-grav-damp)*dt;
    theta+=omega*dt;
    if(theta>crash)return {crash:true,t:+t.toFixed(2),theta:+theta.toFixed(1),omega:+omega.toFixed(1)};
  }
  return {crash:false,theta:+theta.toFixed(1)};
}
console.log('recover 1s gas drop +lean -39, crash103',recover(.24,103,-39));
console.log('recover lean -55',recover(.24,103,-55));
console.log('recover lean -55 heat .12',recover(.12,103,-55));
